  for (let i = 0; i < 150; i++) await emit("billing.plan_changed", { orgId: t.org.id, actorId: null, occurredAt: at as never, from: "free", to: "growth" });
  const json = JSON.parse(await exportActivity(t.actors.admin, { orgId: t.org.id, since: at as never, until: at as never, format: "json" }));
  console.log(json.length, json[0]);
  await expect(exportActivity(t.actors.admin, { orgId: t.org.id, since: "2020-01-02T00:00:00Z" as never, until: at as never, format: "json" })).rejects.toThrow();
});
EOF
